<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,PerformanceMetric};
use App\Services\Analytics\PlatformComparisonGate;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
class PlatformComparisonTest extends TestCase{
 use DatabaseTransactions;
 private function fixture():array{$u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Fixture','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Fixture','currency'=>'USD']);return[$u,$a,$c];}
 private function row($a,$c,array $extra=[]):PerformanceMetric{return PerformanceMetric::create($extra+['metadata'=>['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'meta','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','account_metadata_source'=>'provider-discovery-explicit-1','metric_definition'=>['version'=>'meta-pixel-purchase-1','normalization'=>'strict-meta-operands-1','account_metadata_source'=>'meta-discovery-explicit-1','conversion'=>'offsite_conversion.fb_pixel_purchase','value'=>'offsite_conversion.fb_pixel_purchase']],'connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'provider'=>'meta','currency'=>'USD','date'=>now()->subDay()->toDateString(),'spend'=>100,'impressions'=>1000,'clicks'=>50,'conversions'=>5,'reach'=>600,'frequency'=>1.666667]);}
 public function test_gate_never_ranks_and_unknown_dimensions_block():void{$s=fn($p,$cur,$att,$conv)=>['account_id'=>1,'provider'=>$p,'currency'=>$cur,'window'=>['start'=>'2026-11-01','end'=>'2026-11-07','timezone'=>'UTC'],'spend'=>'100','conversions'=>$conv,'attribution'=>$att,'definition_key'=>$p.':purchase'];$r=(new PlatformComparisonGate)->compare([$s('meta','USD','a','50'),$s('tiktok','EGP','b','10')]);$this->assertNull($r['ranking']);$p=$r['pairs'][0];$this->assertSame('not_comparable',$p['verdict']);$this->assertSame('different',$p['checks']['currency']);$this->assertSame('different',$p['checks']['attribution']);$this->assertSame('different',$p['checks']['conversion_definition']);$this->assertSame('below_guard',$p['checks']['sample_size']);$this->assertSame('unknown',$p['checks']['objective']);$this->assertSame('unknown',$p['checks']['audience']);$this->assertSame('unknown',$p['checks']['funnel_position']);$same=(new PlatformComparisonGate)->compare([$s('meta','USD','a','50'),$s('meta','USD','a','50')]);$this->assertSame('not_comparable',$same['pairs'][0]['verdict']);$this->assertContains('cross_provider_outcome_equivalence: not established',$same['pairs'][0]['blockers']);}
 public function test_endpoint_scopes_accounts_and_shows_totals_without_a_merged_total():void{\Illuminate\Support\Carbon::setTestNow(\Illuminate\Support\Carbon::parse('2026-11-23T12:00:00Z'));try{[$u,$a,$c]=$this->fixture();[$u2,$b,$c2]=$this->fixture();$this->row($a,$c,['date'=>'2026-11-20']);$this->actingAs($u,'sanctum')->getJson('/api/v1/analytics/platform-comparison?account_ids[]='.$a->id.'&account_ids[]='.$b->id)->assertNotFound();$r=$this->getJson('/api/v1/analytics/platform-comparison?account_ids[]='.$a->id.'&days=30')->assertOk()->assertJsonPath('data.type','PLATFORM_COMPARABILITY_VIEW')->assertJsonPath('data.ranking',null);$this->assertArrayNotHasKey('total',$r->json('data'));$this->assertSame('insufficient_platforms',$r->json('data.status'));$this->assertSame(1,count($r->json('data.platforms'))+count($r->json('data.excluded')));}finally{\Illuminate\Support\Carbon::setTestNow();}}
}
